-- open requests waiting for the warden, and one rejected request

-- fee payments (amount = base fee + AC surcharge, taken from the room)
SELECT a.allocation_id, rt.base_fee + IF(r.ac, rt.ac_fee, 0), 'UPI', '2026-08-15 10:00:00'
FROM allocation a JOIN bed b ON b.bed_id = a.bed_id JOIN room r ON r.room_id = b.room_id
JOIN room_type rt ON rt.room_type = r.room_type
WHERE a.status = 'Active' AND a.student_id IN (1, 4, 7, 10, 13);
SELECT a.allocation_id, rt.base_fee + IF(r.ac, rt.ac_fee, 0), 'Debit Card', '2026-08-15 10:00:00'
FROM allocation a JOIN bed b ON b.bed_id = a.bed_id JOIN room r ON r.room_id = b.room_id
JOIN room_type rt ON rt.room_type = r.room_type
WHERE a.status = 'Active' AND a.student_id IN (2, 5, 8);
SELECT a.allocation_id, rt.base_fee + IF(r.ac, rt.ac_fee, 0), 'Credit Card', '2026-08-15 10:00:00'
FROM allocation a JOIN bed b ON b.bed_id = a.bed_id JOIN room r ON r.room_id = b.room_id
JOIN room_type rt ON rt.room_type = r.room_type
WHERE a.status = 'Active' AND a.student_id IN (3, 6, 9, 19, 22, 25, 28, 31, 34, 37, 40, 43, 46, 49, 52, 55, 58, 61, 64, 67, 70);

